// Capture shared browser models before the Worker bundler can add server-only
// helpers or rename their bindings. The resulting module contains plain data.
import {writeFile} from 'node:fs/promises';
import {reportMeasure,growthSnapshot} from '../workers/dashboard-growth.mjs';
const source=[reportMeasure,growthSnapshot].map(fn=>fn.toString()).join('\n');
await writeFile(new URL('../workers/dashboard-client-models.mjs',import.meta.url),
  '// Generated by scripts/build_dashboard_client.mjs; edit dashboard-growth.mjs.\n'+
  'export const MODEL_CLIENT = '+JSON.stringify(source)+';\n');
console.log('Dashboard browser models captured before Worker compilation.');
